function updateOpponents() {
    // 获取所有玩家信息，按playerNum排序
    const playerList = [];
    for (let [pid, player] of Object.entries(gameState.playerInfo || {})) {
        playerList.push({ ...player, playerId: pid });
    }
    playerList.sort((a, b) => a.playerNum - b.playerNum);

    // 找到自己的位置
    const myPos = myInfo.playerNum - 1; // 0-3

    // 获取当前出牌玩家
    const sortedPlayerIds = playerList.map(p => p.playerId);
    const currentPlayerId = sortedPlayerIds[gameState.currentPlayer];
    const timeLeft = currentTurnTimeLeft || gameState.turnTimeLeft || 0;

    // 计算相对位置：逆时针顺序 1(下) → 2(右) → 3(上) → 4(左)
    // 从1号位看：右=2号, 上=3号(对家), 左=4号
    const positions = ['Right', 'Top', 'Left'];
    const relativeOffsets = [1, 2, 3]; // 右家=逆时针下一个, 上家=对家, 左家=逆时针上一个

    positions.forEach((pos, idx) => {
        const targetPlayerNum = ((myPos + relativeOffsets[idx]) % 4) + 1;
        const targetPlayer = playerList.find(p => p.playerNum === targetPlayerNum);

        if (targetPlayer) {
            const pid = targetPlayer.playerId;
            const count = gameState.hands[pid]?.count || 0;
            const finished = targetPlayer.finished;
            const rank = targetPlayer.rank;
            const isCurrentTurn = (pid === currentPlayerId);

            // 更新牌数 - 只在<=7张时显示
            const countEl = document.getElementById(`op${pos}Count`);
            if (count <= 7 && count > 0 && !finished) {
                countEl.textContent = count;
                countEl.parentElement.style.display = 'block';
                countEl.parentElement.classList.add('warning-blink');
            } else {
                countEl.parentElement.style.display = 'none';
                countEl.parentElement.classList.remove('warning-blink');
            }

            // 更新名字和队伍颜色，如果已出完显示名次
            const nameEl = document.getElementById(`op${pos}Name`);
            let nameHtml = targetPlayer.name;
            if (finished && rank > 0) {
                nameHtml += ` <span class="rank-badge">第${rank}名</span>`;
            }
            nameEl.innerHTML = nameHtml;
            nameEl.className = `opponent-name ${targetPlayer.team === 1 ? 'team1' : 'team2'}`;

            // 显示牌背或名次（叠加样式）
            const cardsContainer = document.getElementById(`op${pos}Cards`);
            cardsContainer.innerHTML = '';

            if (finished && rank > 0) {
                // 显示名次
                const rankDiv = document.createElement('div');
                rankDiv.className = 'finished-rank';
                rankDiv.innerHTML = `🏆<br>第${rank}名`;
                cardsContainer.appendChild(rankDiv);
            } else if (count > 0) {
                // 创建牌背叠加容器
                const stackDiv = document.createElement('div');
                stackDiv.className = 'card-back-stack';

                // 只显示一张牌背
                const back = document.createElement('div');
                back.className = 'card-back';
                stackDiv.appendChild(back);

                // 添加数量标签 - 只在<=7张时显示并闪烁
                if (count <= 7) {
                    const badge = document.createElement('span');
                    badge.className = 'card-count-badge warning';
                    badge.textContent = count;
                    stackDiv.appendChild(badge);
                }

                cardsContainer.appendChild(stackDiv);
            }
        }
    });
}

