            const nameEl = document.getElementById(`op${pos}Name`);
            let nameHtml = targetPlayer.name;
            if (finished && rank > 0) {
                nameHtml += ` <span class="rank-badge">第${rank}名</span>`;
            }
            nameEl.innerHTML = nameHtml;
            nameEl.className = `opponent-name ${targetPlayer.team === 1 ? 'team1' : 'team2'}`;

            // 显示牌背或名次（叠加样式）
            const cardsContainer = document.getElementById(`op${pos}Cards`);
            cardsContainer.innerHTML = '';

            if (finished && rank > 0) {
                // 显示名次
                const rankDiv = document.createElement('div');
                rankDiv.className = 'finished-rank';
                rankDiv.innerHTML = `🏆<br>第${rank}名`;
                cardsContainer.appendChild(rankDiv);
            } else if (count > 0) {
                // 创建牌背叠加容器
                const stackDiv = document.createElement('div');
                stackDiv.className = 'card-back-stack';

                // 只显示一张牌背
                const back = document.createElement('div');
                back.className = 'card-back';
                stackDiv.appendChild(back);

                // 添加数量标签 - 只在<=7张时显示并闪烁
                if (count <= 7) {
                    const badge = document.createElement('span');
                    badge.className = 'card-count-badge warning';
                    badge.textContent = count;
                    stackDiv.appendChild(badge);
                }

                cardsContainer.appendChild(stackDiv);
            }
        }
    });
}

