// 处理回合倒计时更新
let currentTurnTimeLeft = 0;
function handleTurnTimeUpdate(data) {
    currentTurnTimeLeft = data.timeLeft;
    updateTurnTimerDisplay();
    // 同时更新对手区域的倒计时显示
    if (gameState && gameState.started) {
        updateOpponents();
    }
}

// 更新倒计时显示
function updateTurnTimerDisplay() {
    if (!gameState) return;

    // 获取当前出牌玩家
    const playerList = [];
    for (let [pid, player] of Object.entries(gameState.playerInfo || {})) {
        playerList.push({ ...player, playerId: pid });
    }
    playerList.sort((a, b) => a.playerNum - b.playerNum);
    const sortedPlayerIds = playerList.map(p => p.playerId);
    const currentPid = sortedPlayerIds[gameState.currentPlayer];

    // 更新名称旁的时间显示
    ['Left', 'Top', 'Right'].forEach(pos => {
        const nameEl = document.getElementById(`op${pos}Name`);
        if (nameEl && nameEl.classList.contains('current-turn')) {
            updateNameTimer(nameEl);
        }
    });

    // 如果轮到自己，更新自己的倒计时显示
    if (currentPid === playerId) {
        updateMyTimer();
    }

    // 如果轮到自己，在最后5秒显示提示
    if (currentPid === playerId && currentTurnTimeLeft <= 5 && currentTurnTimeLeft > 0) {
        showNotification(`⏰ 剩余 ${currentTurnTimeLeft} 秒！`);
    }
}

// 处理玩家pass事件 - 显示"过"气泡
function handlePlayerPass(data) {
    const passPlayerId = data.playerId;
    const passPlayerName = data.playerName;

    // 检查是否是自己pass
    if (passPlayerId === playerId) {
        // 在自己的出牌区域显示"过"气泡
        const myPlayArea = document.getElementById('myPlayArea');
        if (myPlayArea) {
            const bubble = document.createElement('div');
            bubble.className = 'pass-bubble';
            bubble.textContent = '过';
            bubble.style.position = 'absolute';
            bubble.style.top = '50%';
            bubble.style.left = '50%';
            bubble.style.transform = 'translate(-50%, -50%)';
            myPlayArea.style.position = 'relative';
            myPlayArea.appendChild(bubble);

            setTimeout(() => bubble.remove(), 1000);
        }
        return;
    }

    // 找到该玩家在UI中的位置
    const playerList = [];
    for (let [pid, player] of Object.entries(gameState.playerInfo || {})) {
        playerList.push({ ...player, playerId: pid });
    }
    playerList.sort((a, b) => a.playerNum - b.playerNum);

    const passPlayer = playerList.find(p => p.playerId === passPlayerId);
    if (!passPlayer) return;

