function updateNameTimer(nameEl) {
    if (!nameEl) return;

    // 移除旧计时器
    const oldTimer = nameEl.querySelector('.name-timer');
    if (oldTimer) oldTimer.remove();

    const timeLeft = currentTurnTimeLeft || gameState?.turnTimeLeft || 0;
    if (timeLeft > 0) {
        const timerEl = document.createElement('span');
        timerEl.className = 'name-timer';
