function createCardElement(card, small = false) {
    const el = document.createElement('div');
    el.className = `card ${small ? 'card-small' : ''}`;

    // 判断颜色：优先使用显示花色
    const effectiveSuit = card.displaySuit || card.suit;
    const effectiveRank = card.displayRank || card.rank;

    if (card.isJoker) {
        el.classList.add(card.rank === '大王' ? 'joker-red' : 'joker-black');
    } else if (effectiveSuit === '♥' || effectiveSuit === '♦') {
        el.classList.add('red');
    } else {
        el.classList.add('black');
    }

    if (card.isTrump) {
        el.classList.add('trump');
    }

    // 标准扑克牌布局：左上角数字+花色，中间大花色，右下角数字+花色（倒置）
    const displayRank = card.isJoker ? (card.rank === '大王' ? '大' : '小') : effectiveRank;
    const displaySuit = card.isJoker ? '王' : effectiveSuit;

    // 逢人配标记（放在card顶层）
    const trumpBadge = card.isTrump ? '<span class="trump-badge">配</span>' : '';

    el.innerHTML = `
        ${trumpBadge}
        <div class="corner-top">
            <span class="rank">${displayRank}</span>
            <span class="suit">${displaySuit}</span>
        </div>
        <div class="center-suit">${displaySuit}</div>
        <div class="corner-bottom">
            <span class="rank">${displayRank}</span>
            <span class="suit">${displaySuit}</span>
        </div>
    `;

    return el;
}

// 使用索引集合来跟踪选中的牌
let selectedCardIndices = new Set();

function toggleCardSelection(index, card) {
    const hand = document.getElementById('myHand');
    const cardElements = hand.querySelectorAll('.card');

    // 使用索引来判断是否选中
    if (selectedCardIndices.has(index)) {
        // 取消选中
        selectedCardIndices.delete(index);
        cardElements[index].classList.remove('selected');
        // 清除内联transform样式，让CSS接管
        cardElements[index].style.transform = '';
        // 从 selectedCards 数组中移除对应的牌
        const sortedCards = sortHandCards(gameState.myHand || []);
        const cardToRemove = sortedCards[index];

