function handleRoundEnd(data) {
    const modal = document.getElementById('roundEndModal');
    modal.style.display = 'flex';

    const winnerTeam = data.winner === 1 ? '红队' : '蓝队';
    const myTeam = myInfo.team === 1 ? '红队' : '蓝队';
    const won = myTeam === winnerTeam;

    document.getElementById('roundEndTitle').textContent = won ? '🎉 胜利！' : '😢 本局失败';

    const rankList = document.getElementById('rankList');
    rankList.innerHTML = data.ranks
        .sort((a, b) => a.rank - b.rank)
        .map(r => `
            <div class="rank-item">
                <span class="name">${r.name} (${r.team === 1 ? '红队' : '蓝队'})</span>
                <span class="rank">第${r.rank}名</span>
            </div>
        `).join('');

    const levelInfo = document.getElementById('levelUpInfo');
    // 使用服务器发送的 previousLevel 来显示正确的升级前级别
    const beforeLevel = data.previousLevel || data.teamLevels[data.winner];
    const afterLevel = data.teamLevels[data.winner];
    const currentLevelDisplay = LEVEL_TO_RANK[beforeLevel] || '2';
    const nextLevelDisplay = LEVEL_TO_RANK[afterLevel] || 'A';
    if (data.levelUp > 0) {
        levelInfo.textContent = `${winnerTeam} 升级 ${data.levelUp} 级！ ${currentLevelDisplay} → ${nextLevelDisplay}`;
    } else {
        levelInfo.textContent = `${winnerTeam} 获胜！级别不变: ${nextLevelDisplay}`;

