// 更新选中牌型显示
function updateSelectedCardsInfo() {
    const infoEl = document.getElementById('selectedCardsText');
    if (!infoEl) return;

    if (selectedCards.length === 0) {
        infoEl.textContent = '请选择要出的牌';
        infoEl.style.color = '#333';
        return;
    }

    // 分析选中的牌，识别逢人配应该代替的牌
    const displayCards = analyzeSelectedCards(selectedCards);

    // 按代替后的值排序显示
    const cardsText = displayCards.map(c => {
        if (c.isTrump) {
            // 逢人配显示为代替的牌+配字
            return `<span style="color:#ff6b6b">${c.displaySuit}${c.displayRank}<small>配</small></span>`;
        }
        return `${c.suit}${c.rank}`;
    }).join(' ');

    // 尝试识别牌型（客户端简单验证）
    const playType = identifyPlayType(selectedCards);

    if (playType) {
        infoEl.innerHTML = `<span style="color: #006400;">${cardsText}</span> → <strong>${playType.name}</strong>`;
    } else {
        infoEl.innerHTML = `<span style="color: #8B0000;">${cardsText}</span> → <strong style="color: #8B0000;">无效牌型</strong>`;
    }
}

// 分析选中的牌，确定逢人配应该代替什么牌
function analyzeSelectedCards(cards) {
    const trumpCards = cards.filter(c => c.isTrump);
