        room.broadcast({
            type: 'playerReconnected',
            playerId: foundPid,
            playerName: foundPlayer.name,
            message: `${foundPlayer.name} 已重新连接`
        });
        room.broadcastPlayerList();
        console.log(`玩家重连: ${foundPlayer.name} -> ${data.roomId}`);
